<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/app/actions.php';
$error='';
try{post_action();}catch(Throwable $e){
    try { if (db()->inTransaction()) db()->rollBack(); } catch (Throwable $ignored) {}
    $error=$e instanceof PDOException?'A database error occurred. Confirm MySQL is running and your database settings are correct.':$e->getMessage();
    error_log('SANDUK: '.$e->getMessage());
}
$user=current_user();$uid=(int)($user['id']??0);
$page=substr((string)($_GET['page']??''),0,30);
$gid=filter_var($_GET['group']??0,FILTER_VALIDATE_INT)?:0;
$group=null;$groupError='';
if($gid && $user){try{$group=group_access($gid,$uid);}catch(Throwable $e){$groupError='Group unavailable.';$gid=0;}}
if(!$user)$page=in_array($page,['login','register'],true)?$page:'home';
elseif(!$group && !in_array($page,['admin','profile','support'],true))$page='groups';
elseif($group && $page==='')$page='overview';
if($page==='admin' && (!$user || !$user['is_super_admin']))$page='groups';
$myGroups=$user?q('SELECT g.* FROM `groups` g JOIN memberships m ON m.group_id=g.id WHERE m.user_id=? AND m.status="active" ORDER BY g.created_at DESC',[$uid])->fetchAll():[];
function field(string $name,string $label,string $type='text',string $value='',string $attrs='',bool $required=true):void {
    $req=$required?' required':'';
    echo '<label>'.h($label).'<input type="'.h($type).'" name="'.h($name).'" value="'.h($value).'" '.$attrs.$req.'></label>';
}
function form_begin(string $action,?int $gid=null):void {echo '<form method="post" class="stack"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="action" value="'.h($action).'">';if($gid)echo '<input type="hidden" name="group_id" value="'.$gid.'">';}
function action_button(string $action,int $gid,int $id,string $decision,string $label,string $entity='request_id'):void {
    form_begin($action,$gid);echo '<input type="hidden" name="'.h($entity).'" value="'.$id.'"><input type="hidden" name="decision" value="'.h($decision).'"><button type="submit" class="small-btn" data-confirm="Confirm this action?">'.h($label).'</button></form>';
}

