<main class="container narrow"><h1>Platform support</h1><section class="card"><h2>Open a support request</h2><?php form_begin('ticket');field('subject','Subject');?><label>Describe the problem<textarea name="message" maxlength="2000" required></textarea></label><button type="submit" class="button">Send request</button></form></section><section class="card"><h2>Your tickets</h2><?php foreach(q('SELECT * FROM support_tickets WHERE user_id=? ORDER BY created_at DESC LIMIT 50',[$uid])->fetchAll() as $t):?><p><strong><?=h($t['subject'])?></strong> <?=pill($t['status'])?><br><?=h($t['message'])?></p><?php endforeach;?></section></main>
