$users=q('SELECT id,full_name,email,is_suspended,created_at FROM users ORDER BY created_at DESC LIMIT 100')->fetchAll();$groups=q('SELECT g.*,u.full_name AS chair_name FROM `groups` g JOIN users u ON u.id=g.chairperson_id ORDER BY g.created_at DESC LIMIT 100')->fetchAll();$tickets=q('SELECT t.*,u.full_name FROM support_tickets t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC LIMIT 100')->fetchAll();?>
<main class="container"><h1>Super Admin</h1><p>Platform-wide oversight. Group approvals stay with the Chairperson.</p><div class="stats"><div class="stat"><small>Total users</small><strong><?=h(q('SELECT COUNT(*) FROM users')->fetchColumn())?></strong></div><div class="stat"><small>Savings groups</small><strong><?=h(q('SELECT COUNT(*) FROM `groups`')->fetchColumn())?></strong></div><div class="stat"><small>Open tickets</small><strong><?=h(q('SELECT COUNT(*) FROM support_tickets WHERE status="open"')->fetchColumn())?></strong></div></div>
<section class="card"><h2>Groups</h2><div class="table-wrap"><table><thead><tr><th>Group</th><th>Chairperson</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($groups as $g):?><tr><td><?=h($g['name'])?></td><td><?=h($g['chair_name'])?></td><td><?=pill($g['status'])?></td><td><?php form_begin('admin_group');?><input type="hidden" name="id" value="<?=(int)$g['id']?>"><input type="hidden" name="status" value="<?=$g['status']==='active'?'paused':'active'?>"><button class="small-btn" data-confirm="Change group status?"><?=$g['status']==='active'?'Pause':'Resume'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><h2>Support tickets</h2><div class="table-wrap"><table><thead><tr><th>Member</th><th>Subject</th><th>Message</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($tickets as $t):?><tr><td><?=h($t['full_name'])?></td><td><?=h($t['subject'])?></td><td><?=h($t['message'])?></td><td><?=pill($t['status'])?></td><td><?php if($t['status']==='open'){form_begin('admin_ticket');echo '<input type="hidden" name="id" value="'.(int)$t['id'].'"><button class="small-btn">Resolve</button></form>';}?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><h2>Recent users (100)</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Joined</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=h($u['full_name'])?></td><td><?=h($u['email'])?></td><td><?=format_date($u['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section></main>
